import { readFileSync } from "node:fs";
import { chmodSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";
import {
  candidateText,
  evaluateJob,
  evaluateJobs,
  evaluateStream,
  extractJson,
  JOB_EVAL_PROMPT,
  nowIso,
  saveRecord,
  sourceFact,
  todayIso,
  type ChatMessage,
  type ChatOptions,
  type EvaluateEvent,
  type LlmClient,
} from "@offeru/core";

import { createApp } from "../src/app";
import { SqliteCoreStore } from "../src/store";

// Generated by test/fixtures/gen_job_eval_parity.py from Python app/core/job_eval.py.
const parity = JSON.parse(readFileSync(new URL("./fixtures/job-eval-parity.json", import.meta.url), "utf8")) as {
  profile: Record<string, unknown>;
  memories: Array<Record<string, unknown>>;
  profile_text: string;
  empty_profile_text: string;
  cases: Array<{ job: Record<string, unknown>; raw: string; messages?: ChatMessage[]; options: Record<string, unknown>; result: unknown }>;
  empty_case: { job: Record<string, unknown>; raw: string; messages: ChatMessage[]; result: unknown };
  source_facts: Array<{ job: Record<string, unknown>; fact: [string, string] }>;
};

function scripted(raws: Array<string | null>, seen: Array<{ messages: ChatMessage[]; options?: ChatOptions }> = []): LlmClient {
  let call = 0;
  return {
    async chat(messages, options) {
      seen.push({ messages, options });
      const raw = raws[Math.min(call, raws.length - 1)];
      call += 1;
      return raw;
    },
  };
}

const ctx = (actor = "你") => () => ({ actor, now: nowIso(), today: todayIso() });

let store: SqliteCoreStore | null = null;
afterEach(() => {
  store?.close();
  store = null;
  delete process.env.OFFERU_BOSS_BIN;
});

describe("job evaluation matches Python job_eval", () => {
  it("builds the same candidate text and source facts", () => {
    expect(candidateText(parity.profile, parity.memories)).toBe(parity.profile_text);
    expect(candidateText(null, [])).toBe(parity.empty_profile_text);
    for (const { job, fact } of parity.source_facts) expect(sourceFact(job)).toEqual(fact);
  });

  it("sends the same prompt and normalizes the same way", async () => {
    for (const item of [...parity.cases, { ...parity.empty_case, options: {}, empty: true }] as Array<(typeof parity.cases)[number] & { empty?: boolean }>) {
      const seen: Array<{ messages: ChatMessage[]; options?: ChatOptions }> = [];
      const profileText = item.empty ? parity.empty_profile_text : parity.profile_text;
      const result = await evaluateJob(scripted([item.raw || null], seen), profileText, item.job);
      expect(result, item.raw).toEqual(item.result);
      if (item.messages) expect(seen[0].messages).toEqual(item.messages);
      expect(seen[0].options).toMatchObject({ temperature: 0.2, json: true, maxTokens: 6000 });
    }
    expect(JOB_EVAL_PROMPT).toContain("不要自己写 score");
  });

  it("extracts JSON like Python extract_json", () => {
    expect(extractJson("x {\"a\": \"}{\"} y {\"b\": 1}")).toEqual({ a: "}{" });
    // Python returns the list; every caller only uses dicts, so core returns null for non-objects.
    expect(extractJson("[1]")).toBeNull();
    expect(extractJson("{bad} {\"ok\": true}")).toEqual({ ok: true });
    expect(extractJson("")).toBeNull();
  });
});

const GOOD = JSON.stringify({ score: 70, reasons: ["a", "b", "c"], greeting: "", markdown: "# 结论\nx" });

describe("evaluate stream (Python test_evaluate_stream)", () => {
  it("emits start → job_start/job … → done and persists", async () => {
    store = new SqliteCoreStore(":memory:");
    const first = (await saveRecord(store, { type: "job", data: { company: "甲", title: "后端", jd: "Go" } }, ctx()())).record;
    const second = (await saveRecord(store, { type: "job", data: { company: "乙", title: "算法", jd: "推荐" } }, ctx()())).record;
    const collect = async () => {
      const events: EvaluateEvent[] = [];
      for await (const event of evaluateStream(store!, scripted([GOOD]), { context: ctx() })) events.push(event);
      return events;
    };
    const events = await collect();
    expect(events[0]).toEqual({ type: "start", total: 2 });
    expect(events.slice(1, -1).map((event) => event.type)).toEqual(["job_start", "job", "job_start", "job"]);
    const done = events.at(-1)!;
    expect(done).toMatchObject({ type: "done", count: 2 });
    expect(done.type === "done" && done.change_ids.length).toBe(4);
    expect((await store.get("job", first.id))!.score).toBe(70);
    expect((await store.get("job", second.id))!.score).toBe(70);
    const docs = await store.all("doc", first.id);
    expect(docs).toHaveLength(1);
    expect(docs[0]).toMatchObject({ kind: "evaluation", title: "岗位评估 · 甲 · 后端", body: expect.stringContaining("## 来源") });
    expect(await collect()).toEqual([{ type: "done", count: 0, change_ids: [], items: [], failed: [], remaining: 0 }]);
  });

  it("re-evaluating overwrites the same evaluation doc", async () => {
    store = new SqliteCoreStore(":memory:");
    const job = (await saveRecord(store, { type: "job", data: { company: "甲", title: "后端", jd: "Go" } }, ctx()())).record;
    for (const score of [60, 80]) {
      await evaluateJobs(store, scripted([JSON.stringify({ score, reasons: [], markdown: "# 结论\nx" })]), { ids: [job.id] }, { context: ctx() });
    }
    expect(await store.all("doc", job.id)).toHaveLength(1);
    expect((await store.get("job", job.id))!.score).toBe(80);
  });

  it("chunks the tool form by limit", async () => {
    store = new SqliteCoreStore(":memory:");
    for (let index = 0; index < 3; index += 1) {
      await saveRecord(store, { type: "job", data: { company: `公司${index}`, title: "后端", jd: "Go" } }, ctx()());
    }
    const llm = scripted([GOOD]);
    const run = () => evaluateJobs(store!, llm, { limit: 1 }, { context: ctx() });
    expect(await run()).toMatchObject({ count: 1, remaining: 2 });
    expect(await run()).toMatchObject({ count: 1, remaining: 1 });
    expect(await run()).toMatchObject({ count: 1, remaining: 0 });
    expect((await run()).count).toBe(0);
  });

  it("validates targets and the model up front", async () => {
    store = new SqliteCoreStore(":memory:");
    const bare = (await saveRecord(store, { type: "job", data: { company: "甲", title: "后端" } }, ctx()())).record;
    await expect(evaluateJobs(store, null, {}, { context: ctx() })).rejects.toMatchObject({ code: "invalid", message: expect.stringContaining("没配模型") });
    await expect(evaluateJobs(store, scripted([GOOD]), { ids: [999] }, { context: ctx() })).rejects.toMatchObject({ code: "not_found" });
    await expect(evaluateJobs(store, scripted([GOOD]), { ids: [bare.id] }, { context: ctx() })).rejects.toThrow("还没有 JD");
  });
});

function readSse(text: string): Array<Record<string, unknown>> {
  return text.split("\n\n").filter(Boolean).map((chunk) => JSON.parse(chunk.replace(/^data: /, "")) as Record<string, unknown>);
}

describe("POST /api/jobs/evaluate", () => {
  it("streams SSE events and writes as the request actor", async () => {
    store = new SqliteCoreStore(":memory:");
    const job = (await saveRecord(store, { type: "job", data: { company: "甲", title: "后端", jd: "Go" } }, ctx()())).record;
    const app = createApp({ store, runtime: "worker", storage: "none", llm: () => scripted([GOOD]) });
    const res = await app.request("/api/jobs/evaluate", { method: "POST", body: JSON.stringify({ ids: [job.id] }), headers: { "Content-Type": "application/json" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toContain("text/event-stream");
    const events = readSse(await res.text());
    expect(events.map((event) => event.type)).toEqual(["start", "job_start", "job", "done"]);
    expect(events[2]).toMatchObject({ id: job.id, label: "甲 · 后端", score: 70, reasons: ["a", "b", "c"], greeting: "" });
    expect((await store.changes(5)).every((change) => change.actor === "你")).toBe(true);
  });

  it("answers 400 before streaming when there is no model", async () => {
    store = new SqliteCoreStore(":memory:");
    const app = createApp({ store, runtime: "worker", storage: "none" });
    const res = await app.request("/api/jobs/evaluate", { method: "POST" });
    expect(res.status).toBe(400);
    expect(await res.json()).toMatchObject({ code: "invalid", detail: expect.stringContaining("没配模型") });
  });

  it("ends with an error event when the model gave nothing usable", async () => {
    store = new SqliteCoreStore(":memory:");
    await saveRecord(store, { type: "job", data: { company: "甲", title: "后端", jd: "Go" } }, ctx()());
    const app = createApp({ store, runtime: "worker", storage: "none", llm: () => scripted([null]) });
    const events = readSse(await (await app.request("/api/jobs/evaluate", { method: "POST", body: "{}" })).text());
    expect(events.at(-1)).toEqual({ type: "error", detail: "模型没返回可用的评估，岗位没动：甲 · 后端", code: "invalid" });
    expect(await store.all("doc")).toHaveLength(0);
  });
});

describe("/api/applications/boss-login", () => {
  it("is 501 on the stateless Worker", async () => {
    store = new SqliteCoreStore(":memory:");
    const app = createApp({ store, runtime: "worker", storage: "none" });
    expect((await app.request("/api/applications/boss-login")).status).toBe(501);
  });

  it("drives the boss CLI's QR login on the Node companion", async () => {
    store = new SqliteCoreStore(":memory:");
    const app = createApp({ store, runtime: "node", storage: "sqlite" });
    const missing = await (await app.request("/api/applications/boss-login")).json();
    expect(missing).toEqual({ installed: false, status: "idle", message: "", qr: null, logged_in: null, capabilities: { sync: false, search: false } });
    expect((await app.request("/api/applications/boss-login/start", { method: "POST" })).status).toBe(400);
    expect((await app.request("/api/applications/boss-login/hack", { method: "POST" })).status).toBe(400);

    const dir = mkdtempSync(join(tmpdir(), "boss-"));
    const script = join(dir, "boss.mjs");
    writeFileSync(script, `#!/usr/bin/env node
import { writeFileSync } from "node:fs";
const [cmd, arg] = process.argv.slice(2);
if (cmd === "status") console.log(JSON.stringify({ credential_present: true, search_authenticated: false }));
else if (cmd === "logout") console.log(JSON.stringify({ ok: true }));
else if (cmd === "login-qr") {
  writeFileSync(arg, Buffer.from([0x89, 0x50, 0x4e, 0x47]));
  console.log(JSON.stringify({ event: "qr" }));
  setTimeout(() => {}, 60000);
}
`);
    chmodSync(script, 0o755);
    process.env.OFFERU_BOSS_BIN = script;

    const started = await (await app.request("/api/applications/boss-login/start", { method: "POST" })).json() as Record<string, unknown>;
    expect(started).toMatchObject({ installed: true, logged_in: null });
    let view = started;
    for (let i = 0; i < 50 && view.status !== "waiting"; i += 1) {
      await new Promise((resolve) => setTimeout(resolve, 50));
      view = await (await app.request("/api/applications/boss-login")).json() as Record<string, unknown>;
    }
    expect(view).toMatchObject({ status: "waiting", qr: expect.stringMatching(/^data:image\/png;base64,/) });
    const cancelled = await (await app.request("/api/applications/boss-login/cancel", { method: "POST" })).json();
    expect(cancelled).toEqual({ installed: true, status: "idle", message: "", qr: null, logged_in: true, capabilities: { sync: true, search: false } });
    const loggedOut = await app.request("/api/applications/boss-login/logout", { method: "POST" });
    expect(loggedOut.status).toBe(200);
  });
});
